import raw from '../generated/dataset.json';
import type { Dataset } from './schema';

/** The dataset is generated by `npm run data:build` from data/ (see scripts/build-dataset.ts). */
export const dataset = raw as unknown as Dataset;

export const topicById = new Map(dataset.topics.map((t) => [t.id, t]));
export const questionById = new Map(dataset.questions.map((q) => [q.id, q]));
export const candidateById = new Map(dataset.candidates.map((c) => [c.id, c]));
export const questionsByTopic = new Map(dataset.topics.map((t) => [t.id, dataset.questions.filter((q) => q.topic === t.id)]));
